-- Name: token_ledger_block_double_resolution(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.token_ledger_block_double_resolution() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.reservation_id IS NOT NULL
       AND NEW.entry_type IN ('commit', 'release')
       AND EXISTS (
           SELECT 1 FROM token_ledger
           WHERE reservation_id = NEW.reservation_id
             AND entry_type IN ('commit', 'release')
       ) THEN
        RAISE EXCEPTION 'reservation % already resolved', NEW.reservation_id
            USING ERRCODE = 'P0001',
                  HINT = 'reservation_already_resolved';
    END IF;
    RETURN NEW;
END;
$$;


