    degraded_used bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT usage_counters_cycle_type_check CHECK (((cycle_type)::text = ANY ((ARRAY['weekly'::character varying, 'monthly'::character varying])::text[]))),
    CONSTRAINT usage_counters_degraded_used_check CHECK ((degraded_used >= 0)),
    CONSTRAINT usage_counters_used_check CHECK ((used >= 0))
);


ALTER TABLE public.usage_counters OWNER TO postgres;

